using System;
using UnityEngine;

namespace Framework.Input
{
    /// <summary>
    /// 入力システムの共通インターフェース。
    ///
    /// キーボード、ゲームパッドなどの物理入力を
    /// ゲーム内の操作として取得するための仕組みを定義する。
    ///
    /// 特定の入力アセットには依存せず、
    /// 様々な入力システムへの差し替えに対応する。
    /// </summary>
    /// <typeparam name="TAction">
    /// ゲーム内の操作を識別する列挙型。
    /// </typeparam>
    public interface IInputProvider<TAction>
        where TAction : struct, Enum
    {
        #region Properties

        /// <summary>
        /// 入力システムが初期化され、
        /// 入力を取得できる状態か。
        /// </summary>
        bool IsInitialized { get; }

        /// <summary>
        /// 入力の取得が有効になっているか。
        /// </summary>
        bool IsInputEnabled { get; }

        #endregion

        #region Action Methods

        /// <summary>
        /// 指定された操作が登録されているか確認する。
        /// </summary>
        /// <param name="action">
        /// 確認する操作
        /// </param>
        /// <returns>
        /// 操作が登録されている場合はtrue
        /// </returns>
        bool HasAction(TAction action);

        #endregion

        #region Button Methods

        /// <summary>
        /// 指定された操作が押されているか取得する。
        ///
        /// ボタンが押されている間はtrueを返す。
        /// </summary>
        /// <param name="action">
        /// 取得する操作
        /// </param>
        /// <returns>
        /// ボタンが押されている場合はtrue
        /// </returns>
        bool GetButton(TAction action);

        /// <summary>
        /// 指定された操作が押された瞬間を取得する。
        ///
        /// 入力が開始されたフレームのみtrueを返す。
        /// </summary>
        /// <param name="action">
        /// 取得する操作
        /// </param>
        /// <returns>
        /// ボタンが押されたフレームの場合はtrue
        /// </returns>
        bool GetButtonDown(TAction action);

        /// <summary>
        /// 指定された操作が離された瞬間を取得する。
        ///
        /// 入力が終了したフレームのみtrueを返す。
        /// </summary>
        /// <param name="action">
        /// 取得する操作
        /// </param>
        /// <returns>
        /// ボタンが離されたフレームの場合はtrue
        /// </returns>
        bool GetButtonUp(TAction action);

        #endregion

        #region Axis Methods

        /// <summary>
        /// 指定された操作の1軸入力値を取得する。
        ///
        /// アナログスティックやトリガーなどの
        /// 入力値取得に使用する。
        /// </summary>
        /// <param name="action">
        /// 取得する操作
        /// </param>
        /// <returns>
        /// -1から1までの入力値。
        /// 入力がない場合は0。
        /// </returns>
        float GetAxis(TAction action);

        /// <summary>
        /// 指定された操作の2軸入力値を取得する。
        ///
        /// キャラクター移動やカーソル移動などの
        /// 方向入力取得に使用する。
        /// </summary>
        /// <param name="action">
        /// 取得する操作
        /// </param>
        /// <returns>
        /// 各成分が-1から1までの入力ベクトル。
        /// 入力がない場合はVector2.zero。
        /// </returns>
        Vector2 GetVector2(TAction action);

        #endregion

        #region Control Methods

        /// <summary>
        /// 入力の有効状態を設定する。
        ///
        /// 無効状態では入力取得メソッドが
        /// false、0、Vector2.zeroを返す。
        ///
        /// 操作の登録情報やキー割り当ては維持する。
        /// </summary>
        /// <param name="enabled">
        /// 入力を有効にする場合はtrue
        /// </param>
        void SetInputEnabled(bool enabled);

        #endregion
    }
}
